            ).filter(SqlExperiment.workspace == workspace)

        if model is SqlIssue:
            return query.join(
                SqlExperiment, SqlIssue.experiment_id == SqlExperiment.experiment_id
            ).filter(SqlExperiment.workspace == workspace)

